struct Counter {
    var value = 0
    mutating func increase(by step: Int = 1) {
        value += step
    }
    func describe() -> String {
        "Count: \(value)"
    }
}
var counter = Counter()
counter.increase()
counter.increase(by: 5)
print(counter.describe())

